=<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Workflow Error Alert</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      background-color: #f4f6f8;
      margin: 0;
      padding: 0;
    }
    .container {
      max-width: 600px;
      background: #ffffff;
      margin: 30px auto;
      padding: 20px;
      border-radius: 8px;
      border: 1px solid #d1d5db;
    }
    .header {
      background-color: #dc3545;
      color: white;
      padding: 15px 0px;
      border-radius: 8px 8px 0 0;
      font-size: 18px;
      font-weight: bold;
      text-align: center;
    }
    .content {
      padding: 15px;
      color: #333333;
      line-height: 1.5;
    border: 0.5px solid #cfcfcf

    }
    .label {
      font-weight: bold;
      color: #555555;
    }
    .footer {
      margin-top: 25px;
      font-size: 12px;
      color: #888888;
      text-align: center;
    }
    a.button {
      display: inline-block;
      background-color: #dc3545;
      color: white !important;
      padding: 10px 20px;
      border-radius: 5px;
      text-decoration: none;
      margin-top: 15px;
    }
    a.button:hover {
      background-color: #c82333;
    }
  </style>
</head>
<body>

  <div class="container">
    <div class="header">
      Workflow Error Notification
    </div>
    <div class="content">
      <p>Dear User,</p>
      <p>An error occurred in one of your n8n workflows. Please review the details below:</p>

      <!-- Table for Workflow Details -->
      <center>
      <table  style="width:95%; table-layout: fixed; border-collapse: collapse;" border="1" cellpadding="8" cellspacing="0">
        <tr>
          <td class="label"><nobr>Workflow Name:</nobr></td>
          <td>{{ $node['Error Trigger'].json.workflow.name || "Unknown" }}</td>
        </tr>
        <tr>
          <td class="label"><nobr>Workflow ID:</nobr></td>
          <td>{{ $node['Error Trigger'].json.workflow.id || "N/A" }}</td>
        </tr>
        <tr>
          <td class="label"><nobr>Node Name:</nobr></td>
          <td>{{ $node['Error Trigger'].json.execution.lastNodeExecuted || "Unknown" }}</td>
        </tr>
        <tr>
          <td class="label"><nobr>Run ID:</nobr></td>
          <td>{{ $node['Error Trigger'].json.execution.id || "N/A" }}</td>
        </tr>
        <tr>
          <td class="label"><nobr>Error Message:</nobr></td>
          <td>{{ $node['Error Trigger'].json.execution.error.message || "" }}</td>
        </tr>
      </table>
      </center>

      <a href="{{ $node['Error Trigger'].json.execution.url }}" target="_blank" class="button">Open Workflow</a>
    </div>
    <div class="footer">
      This is an automated message from your n8n automation system.
    </div>
  </div>
</body>
</html>
